def query(c, d):
    print(f"? {c} {d}")
    import sys
    sys.stdout.flush()
    return int(input())

a_xor_c = query(0, 0)
b_xor_d = query(0, 1)

a = 0
b = 0

for i in range(30):
    mask = 1 << i
    if a_xor_c & mask:
        a |= mask
    if b_xor_d & mask:
        b |= mask

